UPDATE roles SET permissions=permissions || '["suppliers.read","suppliers.manage","purchases.read","purchases.write","purchases.receive","purchases.cost"]'::jsonb WHERE name IN ('Owner','Manager');
CREATE TABLE suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES stores,code text NOT NULL,name text NOT NULL,contact_name text NOT NULL DEFAULT '',email text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',company_number text NOT NULL DEFAULT '',payment_terms text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(store_id,code),UNIQUE(id,store_id));
CREATE SEQUENCE purchase_number_sequence;
CREATE SEQUENCE goods_receipt_number_sequence;
CREATE TABLE purchases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES stores,supplier_id uuid NOT NULL,number text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','ordered','partially_received','received','cancelled')),version integer NOT NULL DEFAULT 1 CHECK(version>0),supplier_reference text NOT NULL DEFAULT '',expected_date date,notes text NOT NULL DEFAULT '',cancel_reason text NOT NULL DEFAULT '',subtotal numeric(14,2) NOT NULL CHECK(subtotal>=0),tax numeric(14,2) NOT NULL CHECK(tax>=0),total numeric(14,2) NOT NULL CHECK(total>=0),created_by uuid NOT NULL,device_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),ordered_at timestamptz,UNIQUE(store_id,number),UNIQUE(id,store_id),FOREIGN KEY(supplier_id,store_id) REFERENCES suppliers(id,store_id),FOREIGN KEY(created_by,store_id) REFERENCES employees(id,store_id),FOREIGN KEY(device_id,store_id) REFERENCES devices(id,store_id));
CREATE TABLE purchase_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES stores,purchase_id uuid NOT NULL,product_id uuid NOT NULL,product_name text NOT NULL,sku text NOT NULL,unit text NOT NULL,ordered_quantity numeric(15,3) NOT NULL CHECK(ordered_quantity>0),received_quantity numeric(15,3) NOT NULL DEFAULT 0 CHECK(received_quantity>=0 AND received_quantity<=ordered_quantity),unit_cost numeric(14,2) NOT NULL CHECK(unit_cost>=0),tax_rate numeric(5,2) NOT NULL CHECK(tax_rate>=0 AND tax_rate<=100),subtotal numeric(14,2) NOT NULL CHECK(subtotal>=0),tax numeric(14,2) NOT NULL CHECK(tax>=0),total numeric(14,2) NOT NULL CHECK(total>=0),UNIQUE(purchase_id,product_id),UNIQUE(id,store_id),FOREIGN KEY(purchase_id,store_id) REFERENCES purchases(id,store_id),FOREIGN KEY(product_id,store_id) REFERENCES products(id,store_id));
CREATE TABLE goods_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES stores,purchase_id uuid NOT NULL,number text NOT NULL,delivery_reference text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',employee_id uuid NOT NULL,device_id uuid NOT NULL,subtotal numeric(14,2) NOT NULL CHECK(subtotal>=0),tax numeric(14,2) NOT NULL CHECK(tax>=0),total numeric(14,2) NOT NULL CHECK(total>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(store_id,number),UNIQUE(id,store_id),FOREIGN KEY(purchase_id,store_id) REFERENCES purchases(id,store_id),FOREIGN KEY(employee_id,store_id) REFERENCES employees(id,store_id),FOREIGN KEY(device_id,store_id) REFERENCES devices(id,store_id));
CREATE TABLE goods_receipt_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES stores,receipt_id uuid NOT NULL,purchase_line_id uuid NOT NULL,product_id uuid NOT NULL,product_name text NOT NULL,sku text NOT NULL,unit text NOT NULL,quantity numeric(15,3) NOT NULL CHECK(quantity>0),unit_cost numeric(14,2) NOT NULL CHECK(unit_cost>=0),tax_rate numeric(5,2) NOT NULL CHECK(tax_rate>=0 AND tax_rate<=100),subtotal numeric(14,2) NOT NULL CHECK(subtotal>=0),tax numeric(14,2) NOT NULL CHECK(tax>=0),total numeric(14,2) NOT NULL CHECK(total>=0),UNIQUE(receipt_id,purchase_line_id),FOREIGN KEY(receipt_id,store_id) REFERENCES goods_receipts(id,store_id),FOREIGN KEY(purchase_line_id,store_id) REFERENCES purchase_lines(id,store_id),FOREIGN KEY(product_id,store_id) REFERENCES products(id,store_id));
CREATE TABLE purchasing_commands(store_id uuid NOT NULL REFERENCES stores,request_id uuid NOT NULL,action text NOT NULL,target_id uuid,request_hash text NOT NULL,result jsonb NOT NULL,employee_id uuid NOT NULL,device_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(store_id,request_id),FOREIGN KEY(employee_id,store_id) REFERENCES employees(id,store_id),FOREIGN KEY(device_id,store_id) REFERENCES devices(id,store_id));
ALTER TABLE movements ADD COLUMN purchase_id uuid;
ALTER TABLE movements ADD COLUMN goods_receipt_id uuid;
ALTER TABLE movements ADD CONSTRAINT movement_purchase_store FOREIGN KEY(purchase_id,store_id) REFERENCES purchases(id,store_id);
ALTER TABLE movements ADD CONSTRAINT movement_goods_receipt_store FOREIGN KEY(goods_receipt_id,store_id) REFERENCES goods_receipts(id,store_id);
CREATE INDEX purchases_store_date ON purchases(store_id,created_at DESC);
CREATE INDEX purchases_supplier ON purchases(store_id,supplier_id);
CREATE INDEX receipts_purchase ON goods_receipts(purchase_id,created_at DESC);
CREATE TRIGGER immutable_goods_receipts BEFORE UPDATE OR DELETE ON goods_receipts FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER immutable_goods_receipt_lines BEFORE UPDATE OR DELETE ON goods_receipt_lines FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER immutable_purchasing_commands BEFORE UPDATE OR DELETE ON purchasing_commands FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
